public class Check {
    public static void main(String[] args) {
        PigLatinTranslator t = new PigLatinTranslator();
        String[][] cases = {
            {"apple","appleay"},{"ear","earay"},{"igloo","iglooay"},{"object","objectay"},
            {"under","underay"},{"equal","equalay"},{"pig","igpay"},{"koala","oalakay"},
            {"xenon","enonxay"},{"qat","atqay"},{"chair","airchay"},{"queen","eenquay"},
            {"square","aresquay"},{"therapy","erapythay"},{"thrush","ushthray"},
            {"school","oolschay"},{"yttria","yttriaay"},{"xray","xrayay"},
            {"yellow","ellowyay"},{"rhythm","ythmrhay"},{"my","ymay"},
            {"quick fast run","ickquay astfay unray"}
        };
        int fail = 0;
        for (String[] c : cases) {
            String got = t.translate(c[0]);
            if (!got.equals(c[1])) {
                fail++;
                System.out.println("FAIL " + c[0] + ": expected " + c[1] + " got " + got);
            }
        }
        System.out.println(fail == 0 ? "ALL " + cases.length + " CASES PASSED" : fail + " FAILURES");
        if (fail != 0) System.exit(1);
    }
}
